<script setup lang="ts">
import type { BsDocumentExtractionCopy, BsDocumentExtractionForm, BsDocumentExtractionView, BsJournalImportField } from '../types/journalImportPresentation'
defineProps<{ copy: BsDocumentExtractionCopy; view: BsDocumentExtractionView }>()
const form = defineModel<BsDocumentExtractionForm>('form', { required: true })
const fields: BsJournalImportField[] = ['type', 'date', 'amount', 'account', 'category', 'description', 'reference', 'counterparty', 'currency', 'exchange_rate']
const emit = defineEmits<{ document: [event: Event]; proposal: [event: Event]; reject: []; accept: [] }>()
function value(index: number, field: BsJournalImportField, input: unknown) { form.value = { ...form.value, candidates: form.value.candidates.map((candidate, row) => row === index ? { values: { ...candidate.values, [field]: String(input ?? '') } } : candidate) } }
</script>
<template>
  <BsCard v-if="view.visible" as="section" padding="lg"><BsStack gap="md"><BsHeading :level="2" size="h2">{{ copy.title }}</BsHeading><BsText size="sm" tone="muted">{{ copy.hint }}</BsText><BsBox padding="lg" border radius="control"><BsText emphasis="semibold">{{ copy.boundaryTitle }}</BsText><BsText>{{ copy.boundaryBody }}</BsText></BsBox><BsText v-if="view.error" role="alert" tone="danger">{{ view.error }}</BsText><BsText v-if="view.mismatch" role="alert" tone="danger">{{ view.mismatch }}</BsText>
    <BsGrid :columns="2" gap="md"><BsBox><BsFieldLabel for="document-source-file">{{ copy.documentLabel }}</BsFieldLabel><BsText size="xs" tone="muted">{{ copy.documentHint }}</BsText><BsFileInput id="document-source-file" :key="view.resetKey" accept="application/pdf,image/png,image/jpeg,image/webp" bare @change="emit('document', $event)"/><BsText v-if="view.source" size="xs" tone="muted">{{ view.source }}</BsText></BsBox><BsBox><BsFieldLabel for="document-proposal-file">{{ copy.proposalLabel }}</BsFieldLabel><BsText size="xs" tone="muted">{{ copy.proposalHint }}</BsText><BsFileInput id="document-proposal-file" :key="view.resetKey" accept="application/json,.json" bare @change="emit('proposal', $event)"/></BsBox></BsGrid>
    <BsStack v-if="view.hasProposal" gap="md"><BsBox v-for="(candidate, index) in view.candidates" :key="candidate.id" as="article" padding="lg" border radius="control"><BsHeading :level="3" size="body">{{ candidate.title }}</BsHeading><BsList v-if="candidate.issues.length" marker="none"><BsListItem v-for="issue in candidate.issues" :key="issue.id"><BsText as="strong">{{ issue.code }}</BsText> — {{ issue.message }}</BsListItem></BsList><BsText v-else size="xs" tone="muted">{{ copy.noErrors }}</BsText><BsGrid :columns="2" gap="md"><BsBox v-for="field in fields" :key="field"><BsFloatingField :label="copy.fields[field]"><BsSelect v-if="field === 'type'" :model-value="form.candidates[index]?.values[field]" :label="copy.fields[field]" :options="[{ value: '', label: copy.select }, { value: 'income', label: copy.income }, { value: 'expense', label: copy.expense }]" option-label="label" option-value="value" native @update:model-value="value(index, field, $event)"/><BsInput v-else :model-value="form.candidates[index]?.values[field]" type="text" @update:model-value="value(index, field, $event)"/></BsFloatingField><BsInline gap="md" wrap><BsText as="span" :tone="candidate.fields[field].low ? 'danger' : 'muted'">{{ candidate.fields[field].confidence }}</BsText><BsText v-if="candidate.fields[field].evidence" as="span" tone="muted">{{ copy.evidence }}: {{ candidate.fields[field].evidence }}</BsText></BsInline></BsBox></BsGrid></BsBox><BsCheckbox :model-value="form.reviewed" :label="copy.attestation" @update:model-value="form = { ...form, reviewed: Boolean($event) }"/><BsText v-if="view.incomplete" size="sm" tone="danger">{{ copy.incomplete }}</BsText><BsInline gap="sm" wrap justify="end"><BsButton @click="emit('reject')">{{ copy.reject }}</BsButton><BsButton :disabled="!view.canAccept" variant="accent" @click="emit('accept')">{{ copy.accept }}</BsButton></BsInline></BsStack>
  </BsStack></BsCard>
</template>
